     */
    protected function tearDown() {
        
    }

    /**
     * @todo Implement testGet_id().
     */
    public function testGet_id() {
        $this->assertEquals($this->object->get_id(), 'alumno');
    }

    /**
     * @todo Implement testGet_parametro().
     */
    public function testGet_parametros() {
        $this->assertEquals($this->object->get_parametro('index'), 'index_alumno');
    }

    /**
     * @todo Implement testGet_menu().
     */
    public function testGet_menu() {
        $operaciones = array('cursada', 'examen');
        reset($operaciones);
        
        foreach ($this->object->get_menu() as $opcion) {
            $this->assertEquals(current($operaciones), (string) $opcion['operacion']);
            next($operaciones);
        }
    }

    /**
     * @todo Implement testGet_operacion().
     */
    public function testGet_atributo_operacion() {
        $this->assertEquals($this->object->get_atributo_operacion('cursada', 'url'), 'cursada');
        $this->assertEquals($this->object->get_atributo_operacion('cursada', 'activa'), '1');
        
        $this->assertEquals($this->object->get_atributo_operacion('examen', 'url'), 'examen');
        $this->assertEquals($this->object->get_atributo_operacion('examen', 'activa'), '0');
    }
    
    public function testGet_parametro_operacion() {
        $this->assertEquals($this->object->get_parametro_operacion('cursada', 'cambiar_comision'), '0');
        $this->assertEquals($this->object->get_parametro_operacion('cursada', 'anular_inscripcion'), '1');
        $this->assertEquals($this->object->get_parametro_operacion('cursada', 'emitir_comprobante'), '1');

        $this->assertEquals($this->object->get_parametro_operacion('examen', 'cambiar_comision'), '1');
        $this->assertEquals($this->object->get_parametro_operacion('examen', 'anular_inscripcion'), '0');
        $this->assertEquals($this->object->get_parametro_operacion('examen', 'emitir_comprobante'), '1');
    }
    
    public function testExiste_operacion() {
        $this->assertTrue($this->object->existe_operacion('cursada'));
        $this->assertFalse($this->object->existe_operacion('docentes'));
        $this->assertFalse($this->object->existe_operacion('examen'));
